<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,ref } from 'vue'
import { useRoute } from 'vue-router'
import { ArrowLeft,Code2,FileDiff,Files,Loader2,Play,RefreshCw,Rocket,Save,ShieldCheck,Square,Tag } from 'lucide-vue-next'
import { engineeringApi,type EngineeringDiff,type EngineeringFileSummary,type EngineeringRun,type EngineeringVersion,type RunnerProfile } from '../lib/engineeringApi'

const route=useRoute();const projectId=computed(()=>String(route.params.id??''));const tab=ref<'files'|'versions'|'runner'|'delivery'>('files');const revision=ref(0);const files=ref<EngineeringFileSummary[]>([]);const selectedPath=ref('');const content=ref('');const dirty=ref(false);const versions=ref<EngineeringVersion[]>([]);const snapshotName=ref('RC snapshot');const fromVersion=ref('');const toVersion=ref('');const diff=ref<EngineeringDiff[]>([]);const profiles=ref<RunnerProfile[]>([]);const stack=ref('hono-drizzle');const action=ref('verify');const run=ref<EngineeringRun|null>(null);const gates=ref<any[]>([]);const ready=ref(false);const previews=ref<any[]>([]);const deployments=ref<any[]>([]);const busy=ref('');const error=ref('');let poll:number|undefined
function message(cause:unknown){return cause instanceof Error?cause.message:'请求失败'}
async function loadTree(){const result=await engineeringApi.tree(projectId.value);revision.value=result.revision;files.value=result.files;if(!selectedPath.value&&files.value.length)await openFile(files.value[0].path)}
async function openFile(path:string){if(dirty.value&&!window.confirm('当前文件尚未保存，确认切换？'))return;busy.value='file';try{const result=await engineeringApi.file(projectId.value,path);selectedPath.value=path;content.value=result.file.content;dirty.value=false}catch(cause){error.value=message(cause)}finally{busy.value=''}}
async function save(){if(!selectedPath.value)return;busy.value='save';try{const result=await engineeringApi.save(projectId.value,revision.value,[{path:selectedPath.value,content:content.value}]);revision.value=result.revision;files.value=result.files;dirty.value=false}catch(cause:any){error.value=cause?.code==='ENGINEERING_REVISION_CONFLICT'?'工程已在其他位置更新，请刷新后重试。':message(cause)}finally{busy.value=''}}
async function loadVersions(){const result=await engineeringApi.versions(projectId.value);versions.value=result.versions;if(versions.value.length){fromVersion.value ||= versions.value[0].id;toVersion.value ||= versions.value.at(-1)!.id}}
async function snapshot(){busy.value='snapshot';try{await engineeringApi.snapshot(projectId.value,snapshotName.value);await loadVersions()}catch(cause){error.value=message(cause)}finally{busy.value=''}}
async function compare(){if(!fromVersion.value||!toVersion.value)return;busy.value='diff';try{diff.value=(await engineeringApi.diff(projectId.value,fromVersion.value,toVersion.value)).files}catch(cause){error.value=message(cause)}finally{busy.value=''}}
async function startRun(){busy.value='run';try{run.value=(await engineeringApi.run(projectId.value,stack.value,action.value)).run;startPolling()}catch(cause){error.value=message(cause)}finally{busy.value=''}}
function startPolling(){if(poll)window.clearInterval(poll);poll=window.setInterval(async()=>{if(!run.value)return;try{run.value=(await engineeringApi.runStatus(run.value.id)).run;if(['passed','failed','cancelled'].includes(run.value.status)){window.clearInterval(poll);poll=undefined}}catch{}},1500)}
async function cancel(){if(!run.value)return;await engineeringApi.cancelRun(run.value.id);run.value.status='cancelled';if(poll)window.clearInterval(poll)}
async function loadDelivery(){if(!versions.value.length)await loadVersions();const versionId=versions.value.at(-1)?.id;if(!versionId)return;const[g,p,d]=await Promise.all([engineeringApi.gates(projectId.value,versionId),engineeringApi.previews(projectId.value),engineeringApi.deployments(projectId.value)]);gates.value=g.evidence??[];ready.value=Boolean(g.readyForProduction);previews.value=p.previews??[];deployments.value=d.deployments??[]}
async function preview(){const versionId=versions.value.at(-1)?.id;if(versionId){await engineeringApi.createPreview(projectId.value,versionId);await loadDelivery()}}
async function deploy(environment:'staging'|'production'){const versionId=versions.value.at(-1)?.id;if(versionId){await engineeringApi.deploy(projectId.value,versionId,environment);await loadDelivery()}}
async function load(){error.value='';busy.value='load';try{await Promise.all([loadTree(),loadVersions(),engineeringApi.profiles().then((result)=>{profiles.value=result.profiles;if(result.profiles[0])stack.value=result.profiles[0].id})])}catch(cause){error.value=message(cause)}finally{busy.value=''}}
onMounted(()=>void load());onBeforeUnmount(()=>{if(poll)window.clearInterval(poll)})
</script>

<template><main class="min-h-[calc(100vh-4rem)] pt-20 pb-16"><div class="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8"><div class="flex flex-wrap items-center justify-between gap-3"><RouterLink :to="`/projects/${projectId}`" class="inline-flex items-center gap-2 text-sm text-mut hover:text-ink"><ArrowLeft class="h-4 w-4"/>返回项目</RouterLink><RouterLink :to="`/projects/${projectId}/delivery`" class="text-sm font-semibold text-brand1">打开独立交付页</RouterLink></div><header class="mt-5"><p class="text-xs font-semibold text-brand1">Engineering Workspace</p><h1 class="mt-2 text-3xl font-bold text-ink">工程文件、运行与交付</h1><p class="mt-2 text-sm text-mut">在同一工作区编辑云端源码、创建不可变快照、查看 Diff、运行隔离验证并检查发布门禁。</p></header><p v-if="error" class="mt-4 rounded-xl border border-red-500/25 bg-red-500/5 p-3 text-sm text-red-500">{{ error }}</p><nav class="mt-6 flex flex-wrap gap-2"><button v-for="item in [{id:'files',label:'文件',icon:Files},{id:'versions',label:'版本与 Diff',icon:FileDiff},{id:'runner',label:'Runner',icon:Play},{id:'delivery',label:'交付',icon:Rocket}]" :key="item.id" class="inline-flex items-center gap-2 rounded-xl border px-4 py-2.5 text-sm" :class="tab===item.id?'border-brand1/30 bg-brand1/10 text-brand1':'border-line/10 bg-soft/60 text-sub'" @click="tab=item.id as any;item.id==='delivery'&&loadDelivery()"><component :is="item.icon" class="h-4 w-4"/>{{ item.label }}</button><button class="ml-auto rounded-xl border border-line/10 p-2.5 text-mut" @click="load"><RefreshCw class="h-4 w-4" :class="busy==='load'&&'animate-spin'"/></button></nav>
<section v-if="tab==='files'" class="mt-5 grid min-h-[560px] gap-4 lg:grid-cols-[280px_1fr]"><aside class="overflow-hidden rounded-2xl border border-line/10 bg-soft/60"><div class="border-b border-line/10 px-4 py-3 text-xs font-semibold text-sub">revision {{ revision }} · {{ files.length }} files</div><div class="max-h-[520px] overflow-auto p-2"><button v-for="file in files" :key="file.path" class="flex w-full items-center gap-2 rounded-lg px-3 py-2 text-left font-mono text-[11px]" :class="selectedPath===file.path?'bg-brand1/10 text-brand1':'text-sub hover:bg-ink/5'" @click="openFile(file.path)"><Code2 class="h-3.5 w-3.5 shrink-0"/><span class="truncate">{{ file.path }}</span></button></div></aside><article class="flex min-w-0 flex-col overflow-hidden rounded-2xl border border-line/10 bg-soft/60"><div class="flex items-center justify-between gap-3 border-b border-line/10 px-4 py-3"><span class="truncate font-mono text-xs text-sub">{{ selectedPath||'请选择文件' }}</span><button :disabled="!dirty||busy==='save'" class="inline-flex items-center gap-2 rounded-lg bg-brand1 px-3 py-2 text-xs font-semibold text-white disabled:opacity-40" @click="save"><Loader2 v-if="busy==='save'" class="h-3.5 w-3.5 animate-spin"/><Save v-else class="h-3.5 w-3.5"/>保存</button></div><textarea v-model="content" spellcheck="false" class="min-h-[500px] flex-1 resize-none bg-[#111318] p-4 font-mono text-xs leading-6 text-slate-200 outline-none" @input="dirty=true"/></article></section>
<section v-else-if="tab==='versions'" class="mt-5 grid gap-5 lg:grid-cols-2"><article class="rounded-2xl border border-line/10 bg-soft/60 p-5"><h2 class="font-semibold text-ink">不可变版本</h2><div class="mt-4 flex gap-2"><input v-model="snapshotName" class="min-w-0 flex-1 rounded-xl border border-line/10 bg-app px-3 py-2.5 text-sm"/><button class="rounded-xl bg-brand1 px-4 text-sm font-semibold text-white" @click="snapshot"><Tag class="mr-1 inline h-4 w-4"/>创建快照</button></div><div class="mt-4 grid gap-2"><div v-for="version in versions" :key="version.id" class="rounded-xl border border-line/10 bg-app/50 px-3 py-3 text-xs"><strong class="text-ink">v{{ version.number }} · {{ version.name }}</strong><span class="ml-2 text-faint">{{ version.fileCount }} files · {{ version.createdAt }}</span></div></div></article><article class="rounded-2xl border border-line/10 bg-soft/60 p-5"><h2 class="font-semibold text-ink">版本 Diff</h2><div class="mt-4 grid grid-cols-2 gap-2"><select v-model="fromVersion" class="rounded-xl border border-line/10 bg-app px-3 py-2 text-xs"><option v-for="version in versions" :key="version.id" :value="version.id">from v{{ version.number }}</option></select><select v-model="toVersion" class="rounded-xl border border-line/10 bg-app px-3 py-2 text-xs"><option v-for="version in versions" :key="version.id" :value="version.id">to v{{ version.number }}</option></select></div><button class="mt-3 rounded-xl border border-line/10 px-4 py-2 text-sm" @click="compare">比较</button><div class="mt-4 max-h-96 overflow-auto"><div v-for="item in diff" :key="item.path" class="flex justify-between gap-3 border-b border-line/8 py-2 font-mono text-[11px]"><span class="truncate">{{ item.path }}</span><span :class="item.status==='added'?'text-emerald-600':item.status==='deleted'?'text-red-500':item.status==='modified'?'text-amber-600':'text-faint'">{{ item.status }}</span></div></div></article></section>
<section v-else-if="tab==='runner'" class="mt-5 rounded-2xl border border-line/10 bg-soft/60 p-5"><div class="grid gap-3 sm:grid-cols-3"><select v-model="stack" class="rounded-xl border border-line/10 bg-app px-3 py-3 text-sm"><option v-for="profile in profiles" :key="profile.id" :value="profile.id">{{ profile.name }}</option></select><select v-model="action" class="rounded-xl border border-line/10 bg-app px-3 py-3 text-sm"><option value="verify">verify</option><option value="build">build</option><option value="test">test</option></select><button class="rounded-xl bg-brand1 px-4 text-sm font-semibold text-white" @click="startRun"><Play class="mr-2 inline h-4 w-4"/>启动隔离运行</button></div><div v-if="run" class="mt-5 rounded-xl border border-line/10 bg-[#111318] p-4 text-xs text-slate-200"><div class="flex items-center justify-between"><strong>{{ run.stack }} · {{ run.action }} · {{ run.status }}</strong><button v-if="!['passed','failed','cancelled'].includes(run.status)" class="text-red-400" @click="cancel"><Square class="mr-1 inline h-3.5 w-3.5"/>取消</button></div><pre class="mt-3 max-h-96 overflow-auto whitespace-pre-wrap">{{ run.output||run.error||'等待日志…' }}</pre></div></section>
<section v-else class="mt-5 grid gap-5 lg:grid-cols-3"><article class="rounded-2xl border border-line/10 bg-soft/60 p-5"><h2 class="flex items-center gap-2 font-semibold text-ink"><ShieldCheck class="h-4 w-4 text-brand1"/>发布门禁</h2><div class="mt-3 grid gap-2"><div v-for="gate in gates" :key="gate.gate" class="flex justify-between text-xs"><span class="font-mono text-sub">{{ gate.gate }}</span><span>{{ gate.status }}{{ gate.trusted?' · trusted':'' }}</span></div></div><p class="mt-4 text-xs" :class="ready?'text-emerald-600':'text-amber-600'">{{ ready?'Production 已解锁':'Production 保持锁定' }}</p></article><article class="rounded-2xl border border-line/10 bg-soft/60 p-5"><h2 class="font-semibold text-ink">预览</h2><button class="mt-3 w-full rounded-xl border border-line/10 px-4 py-2.5 text-sm" @click="preview">创建最新版本预览</button><div class="mt-3 text-xs text-faint">{{ previews.length }} 个活动预览</div></article><article class="rounded-2xl border border-line/10 bg-soft/60 p-5"><h2 class="font-semibold text-ink">部署</h2><div class="mt-3 grid gap-2"><button class="rounded-xl border border-line/10 px-4 py-2.5 text-sm" @click="deploy('staging')">部署 Staging</button><button :disabled="!ready" class="rounded-xl bg-brand1 px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-40" @click="deploy('production')">部署 Production</button></div><div class="mt-3 text-xs text-faint">{{ deployments.length }} 条部署记录</div></article></section></div></main></template>
